// Canvas Asteroid Dodge – concise implementation
// The HTML includes <canvas id="game"></canvas>

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // safety
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  // Ship definition
  const ship = {
    w: 40,
    h: 20,
    x: W / 2 - 20,
    y: H - 30,
    speed: 5,
    dir: 0, // -1 left, 1 right
  };

  // Asteroid pool
  const asteroids = [];
  const asteroidSpawnInterval = 1000; // ms
  let lastSpawn = 0;

  let score = 0;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') keys.left = true;
    if (e.key === 'ArrowRight') keys.right = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft') keys.left = false;
    if (e.key === 'ArrowRight') keys.right = false;
  });

  function spawnAsteroid() {
    const radius = 10 + Math.random() * 15;
    const x = Math.random() * (W - radius * 2) + radius;
    const speed = 2 + Math.random() * 3;
    asteroids.push({ x, y: -radius, r: radius, speed });
  }

  function update(dt) {
    if (gameOver) return;

    // Move ship
    ship.dir = 0;
    if (keys.left) ship.dir = -1;
    if (keys.right) ship.dir = 1;
    ship.x += ship.dir * ship.speed;
    ship.x = Math.max(0, Math.min(W - ship.w, ship.x));

    // Spawn asteroids
    if (performance.now() - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Collision detection (simple circle‑rect)
      if (
        a.y + a.r > ship.y &&
        a.x > ship.x &&
        a.x < ship.x + ship.w
      ) {
        gameOver = true;
        break;
      }
      // Remove off‑screen
      if (a.y - a.r > H) asteroids.splice(i, 1);
    }

    // Increment score (per frame)
    score++;
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Ship
    ctx.fillStyle = '#0f0';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);

    // Asteroids
    ctx.fillStyle = '#a00';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });

    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score / 60), 10, 20);

    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f00';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
